import math, random, sys, time
sys.path.insert(0, '~/git/asa/Chemical-Universe')
from chemuniverse.tree import enumerate_exact, children
from chemuniverse.bonds import count_molecules
from chemuniverse.rules import RuleConfig

def key_fine(s, cfg):
    spare = sorted((lab, cfg.max_valence(lab) - bin(a).count('1')) for lab, a in zip(s.labels, s.adj))
    return (tuple(spare), len(s.edges()) - s.n)

def key_coarse(s, cfg):
    c = [0]*5
    for lab, a in zip(s.labels, s.adj):
        c[cfg.max_valence(lab) - bin(a).count('1')] += 1
    return (tuple(c), len(s.edges()) - s.n)

def stratified(front, k, N, el, cfg, rng, key):
    level = {}
    def add(d, c, w):
        s = key(c, cfg)
        if s not in d: d[s] = [c, w]
        else:
            W = d[s][1] + w
            if rng.random() < w / W: d[s][0] = c
            d[s][1] = W
    for f in front: add(level, f, 1.0)
    est = []
    for n in range(k + 1, N + 1):
        nxt = {}
        for node, w in level.values():
            for c in children(node, el, cfg): add(nxt, c, w)
        level = nxt
        est.append(sum(w * count_molecules(c, cfg) for c, w in level.values()))
    return est

