                v = c[(i + 1) % k]
                e = (min(u, v), max(u, v))
                if self.edge_ring.get(e, 99) > k:
                    self.edge_ring[e] = k
                if (self.atom_ring[u] or 99) > k:
                    self.atom_ring[u] = k
