  out.push({n:m,central:Math.log10(cum),low:Math.log10(Math.max(cum-2*sd,cum/10)),high:Math.log10(cum+2*sd),kind:exact?'exact':'sampled',se:sd,cum});}
 const N=rows.length,per=rows.map(r=>Math.log10(r[1])),d=per[N-1]-per[N-2];
