import json, math
s=open('docs/data.js').read(); d=json.loads(s[s.index('{'):s.rstrip().rindex(';')])
sets=d['sets']; print(d['params'])
def tot(k):
    rows=sets[k]['rows']; return sum(r[1] for r in rows), math.sqrt(sum(r[2]**2 for r in rows))
bad=0; worst=0
for k in sets:
    base,h=k.split('_h'); h=int(h)
    sups=[]
    if h<4: sups.append(f"{base}_h{h+1}")
    for e in 'NOS':
        if e not in base:
            nb='C'+''.join(x for x in 'NOS' if x in base or x==e); sups.append(f"{nb}_h{h}")
    for s2 in sups:
        a,sa=tot(k); b,sb=tot(s2)
        if b<a:
            z=(a-b)/math.hypot(sa,sb); worst=max(worst,z); bad+=1
            print(f"{k} {a:.3g}±{sa:.2g} > {s2} {b:.3g}±{sb:.2g}  z={z:.1f}")
print('violations',bad,'worst z',round(worst,2))
print('rel SE at 12:', sorted(round(sets[k]['rows'][-1][2]/sets[k]['rows'][-1][1],3) for k in sets)[::8])
EOF

